#nullable enable
namespace CardGame.Core.NativeOwners;
internal sealed class ProgramDrawDiscardWindowObservers(Func<RuntimeEntries.CoreGameEngineAttributedMarkerEventsEntries> getCoreGameEngineAttributedMarkerEventsRuntime, Func<RuntimeEntries.CharacterYanPuOlEntries> getCharacterYanPuOlRuntime, Func<RuntimeEntries.CharacterGuoYuanMobileShiEntries> getCharacterGuoYuanMobileShiRuntime, Func<RuntimeEntries.CoreGameEngineRecipientCategoryMarksEntries> getCoreGameEngineRecipientCategoryMarksRuntime, Func<RuntimeEntries.DeferredRuntime<EngineOwners.CharacterZhangShiPingOlRuntime>> getCharacterZhangShiPingOlRuntime, Func<RuntimeEntries.DeferredRuntime<EngineOwners.CharacterHanSongAnniversaryRuntime>> getCharacterHanSongAnniversaryRuntime) : IProgramDrawDiscardWindowObservers
{
    public IReadOnlyList<ProgramTriggerCandidate> IncludeAttributedDrawObservers(CharacterState subject, IReadOnlyList<ProgramTriggerCandidate> existing) => getCoreGameEngineAttributedMarkerEventsRuntime().IncludeAttributedDrawObservers(subject, existing);
    public IReadOnlyList<ProgramTriggerCandidate> IncludeYanPuDrawObservers(CharacterState subject, IReadOnlyList<ProgramTriggerCandidate> existing) => getCharacterYanPuOlRuntime().IncludeYanPuDrawObservers(subject, existing);
    public IReadOnlyList<ProgramTriggerCandidate> IncludeShiGyDrawObservers(CharacterState subject, IReadOnlyList<ProgramTriggerCandidate> existing) => getCharacterGuoYuanMobileShiRuntime().IncludeShiGyDrawObservers(subject, existing);
    public IReadOnlyList<ProgramTriggerCandidate> IncludeRecipientCategoryGiftObservers(CharacterState owner, IReadOnlyList<ProgramTriggerCandidate> existing) => getCoreGameEngineRecipientCategoryMarksRuntime().IncludeRecipientCategoryGiftObservers(owner, existing);
    public IReadOnlyList<ProgramTriggerCandidate> IncludeHongjiPhaseCandidates(CharacterState owner, SkillProgramTriggerWindow window, IReadOnlyList<ProgramTriggerCandidate> existing) => getCharacterZhangShiPingOlRuntime().Value.IncludeHongjiPhaseCandidates(owner, window, existing);
    public IReadOnlyList<ProgramTriggerCandidate> AppendAnniversaryHanSongDrawEndedCandidates(CharacterState owner, IReadOnlyList<ProgramTriggerCandidate> existing) => getCharacterHanSongAnniversaryRuntime().Value.AppendAnniversaryHanSongDrawEndedCandidates(owner, existing);
}
